import copy, math
from work import evaluate
p = {'base_unit':'m','units':{'m':1,'cm':0.01},'unique':True}
cases = [
 ({'rows':[{'id':'a','amount':2,'unit':'cm'},{'id':'b','amount':3}]}, {'ok':True,'records':[{'id':'a','amount':0.02,'unit':'m'},{'id':'b','amount':3,'unit':'m'}],'errors':[]}),
 ({'rows':[{'id':'','amount':-1,'unit':'x'},{'id':'a','amount':True},{'id':'b','amount':float('inf')},{'id':'c','amount':1,'unit':'x'},{'id':'d','amount':1},{'id':'d','amount':2}]}, {'ok':False,'records':[],'errors':[{'row':0,'cause':'id'},{'row':1,'cause':'amount'},{'row':2,'cause':'amount'},{'row':3,'cause':'unit'},{'row':5,'cause':'duplicate'}]})
]
for request, expected in cases:
 before = copy.deepcopy(request)
 assert evaluate(request,p) == expected, (evaluate(request,p), expected)
 assert request == before
assert evaluate({'rows':[{'id':'x','amount':-1},{'id':'x','amount':1}]},p) == {'ok':False,'records':[],'errors':[{'row':0,'cause':'amount'},{'row':1,'cause':'duplicate'}]}
assert evaluate({'rows':[{'id':'x','amount':1,'unit':'bad'},{'id':'x','amount':True}]},p) == {'ok':False,'records':[],'errors':[{'row':0,'cause':'unit'},{'row':1,'cause':'amount'}]}
print('edge, priority, duplicate, and immutability checks passed')

